<?php
namespace App\Services\Hr;use App\Jobs\GenerateHrReportArtifact;use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;
class HrReportRunService{
public function queue(object$view,?object$schedule,string$asOf,string$format,string$userId,string$idempotencyKey):object{
$existing=DB::table('hr_report_runs')->where('idempotency_key',$idempotencyKey)->first();if($existing){if($existing->status==='queued')GenerateHrReportArtifact::dispatch($existing->id);return$existing;}
$filters=json_decode($view->filter_contract,true)?:[];$columns=json_decode($view->column_contract,true)?:[];$privacy=['legal_entity_id'=>$view->company_id,'authorization_rechecked_at_generation'=>true,'minimum_group_suppression_required'=>in_array($view->report_kind,['analytics_snapshots','workforce_plans'],true),'employee_level_export'=>false];$request=['view_checksum'=>$view->view_checksum,'as_of_date'=>$asOf,'format'=>$format,'filters'=>$filters,'columns'=>$columns,'privacy'=>$privacy];$checksum=hash('sha256',json_encode($request,JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR));
$run=DB::transaction(function()use($view,$schedule,$asOf,$format,$userId,$idempotencyKey,$filters,$columns,$privacy,$checksum){$jobId=(string)Str::uuid();DB::table('domain_transfer_jobs')->insert(['id'=>$jobId,'domain'=>'hr','company_id'=>$view->company_id,'direction'=>'export','job_type'=>'hr_'.$view->report_kind,'format'=>$format,'state'=>'queued','requested_by'=>$userId,'queued_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);$id=(string)Str::uuid();DB::table('hr_report_runs')->insert(['id'=>$id,'company_id'=>$view->company_id,'saved_view_id'=>$view->id,'schedule_id'=>$schedule?->id,'transfer_job_id'=>$jobId,'run_kind'=>$schedule?'scheduled':'manual','as_of_date'=>$asOf,'cutoff_at'=>now(),'filter_snapshot'=>json_encode($filters,JSON_THROW_ON_ERROR),'column_snapshot'=>json_encode($columns,JSON_THROW_ON_ERROR),'privacy_snapshot'=>json_encode($privacy,JSON_THROW_ON_ERROR),'request_checksum'=>$checksum,'idempotency_key'=>$idempotencyKey,'status'=>'queued','requested_by'=>$userId,'queued_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);return DB::table('hr_report_runs')->find($id);});GenerateHrReportArtifact::dispatch($run->id);return$run;}}
